// show/hide filter; an event with no calendar belongs to the default one.
func eventCalendarID(e *bongov1.Event) string {
	if e.CalendarId == "" {
		return "default"
	}
	return e.CalendarId
}

func eventBlockColourClass(e *bongov1.Event, calColors map[string]string) string {
	return CalendarColourClass(eventBlockColor(e, calColors))
}

// EventColourClass is the cal-colour-* class for an event's calendar.
func EventColourClass(e *bongov1.Event, calColors map[string]string) string {
	return eventBlockColourClass(e, calColors)
}

func calendarTopClass(minutes int) string {
	if minutes < 0 {
		minutes = 0
	}
	if minutes > 1439 {
		minutes = 1439
	}
	return fmt.Sprintf("cal-top-%d", minutes)
}

func calendarHeightClass(minutes int) string {
	if minutes < 30 {
		minutes = 30
	}
	if minutes > 1440 {
		minutes = 1440
	}
	return fmt.Sprintf("cal-height-%d", minutes)
}

func CalendarColourClass(hex string) string {
	type paletteEntry struct {
		name    string
		r, g, b int
	}
	palette := []paletteEntry{
		{"blue", 59, 130, 246},
		{"green", 34, 197, 94},
		{"indigo", 99, 102, 241},
		{"orange", 245, 158, 11},
		{"red", 239, 68, 68},
		{"violet", 139, 92, 246},
		{"yellow", 234, 179, 8},
	}
	r, g, b, ok := parseHexColour(hex)
	if !ok {
		return "cal-colour-blue"
	}
	bestName := "blue"
	bestDist := -1
	for _, p := range palette {
		dr := r - p.r
		dg := g - p.g
		db := b - p.b
		dist := dr*dr + dg*dg + db*db
		if bestDist == -1 || dist < bestDist {
			bestDist = dist
			bestName = p.name
		}
	}
	return "cal-colour-" + bestName
}

func parseHexColour(hex string) (int, int, int, bool) {
	if len(hex) != 7 || hex[0] != '#' {
		return 0, 0, 0, false
	}
	var r, g, b int
	_, err := fmt.Sscanf(hex, "#%02x%02x%02x", &r, &g, &b)
	if err != nil {
		return 0, 0, 0, false
	}
	return r, g, b, true
}

// isCustomRrule reports whether a stored rule is not one of the form presets,
// so the select can offer it and round-trip it unchanged.
func isCustomRrule(r string) bool {
	switch r {
	case "", "FREQ=DAILY", "FREQ=WEEKLY", "FREQ=MONTHLY", "FREQ=YEARLY":
		return false
	}
	return true
}

func eventRrule(e *bongov1.Event) string {
	if e == nil {
		return ""
	}
	return e.Rrule
}

func eventReminderMinutes(e *bongov1.Event) string {
	if e == nil || e.ReminderMinutes == 0 {
		return "0"
	}
	return fmt.Sprint(e.ReminderMinutes)
}

// MiniCalDay holds data for one day in the mini calendar.
type MiniCalDay struct {
	Day        int
	IsToday    bool
	IsSelected bool
	InMonth    bool
}

func miniCalDays(today time.Time, year, month, selectedDay int) []MiniCalDay {
	firstDay := time.Date(year, time.Month(month), 1, 0, 0, 0, 0, today.Location())
	lastDay := firstDay.AddDate(0, 1, -1).Day()

	weekday := int(firstDay.Weekday())
	if weekday == 0 {
		weekday = 7
	}

	todayYear, todayMonth, todayDay := today.Date()

	var days []MiniCalDay

	// Padding for days before month start.
	for i := 1; i < weekday; i++ {
		days = append(days, MiniCalDay{Day: 0})
	}

	for d := 1; d <= lastDay; d++ {
		days = append(days, MiniCalDay{
			Day:        d,
			IsToday:    year == todayYear && time.Month(month) == todayMonth && d == todayDay,
			IsSelected: d == selectedDay,
			InMonth:    true,
		})
	}

	return days
}

func firstOfMonth(ctx context.Context, year, month int) time.Time {
	return time.Date(year, time.Month(month), 1, 0, 0, 0, 0, calendarNow(ctx).Location())
}

func miniPrevYear(year, month int) int {
	if month <= 1 {
		return year - 1
	}
	return year
}

func miniPrevMonth(month int) int {
	if month <= 1 {
		return 12
	}
	return month - 1
}

func miniNextYear(year, month int) int {
	if month >= 12 {
		return year + 1
	}
	return year
}

func miniNextMonth(month int) int {
	if month >= 12 {
		return 1
	}
	return month + 1
}

// AgendaItem is one row of the agenda. TimeLabel is formatted by the handler
// in the user's zone; it is empty for an all-day event.
